class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int l = 0, sum = 0, best = INT_MAX;
        for (int r = 0; r < (int)nums.size(); r++) {
            sum += nums[r];
            while (sum >= target) {
                best = min(best, r - l + 1);
                sum -= nums[l];
                l++;
            }
        }
        return best == INT_MAX ? 0 : best;
    }
};
